; FRIEZA module: Frieza's mainline arc, the ground fight, Thanatos's warm-up,
; the fed Mana Beast, finale deaths and the victory flow.
; Port of engine/frieza.js and its helpers (frieza-events, -intro, -staging,
; -sprite, -combat, -arena, -crisis, beast-challenge, battle-retry,
; boss-rush-death, boss-victory, fortress-collapse).
; See docs/agents/snes-port/frieza.md for the scene list, timings, resources
; and the API the orbit stream uses.
;
; Resources:
;   code  $A6:8000-FFFF (!CODE_FRIEZA)    data  $E6:0000-7FFF (!DATA_FRIEZA)
;   art   $F0:0000-7FFF (generated by snes/gen/frieza.mjs)
;   WRAM  $7E:DB00-DBBF (!RAM_FRIEZA)     SRAM  !PERSIST_FRIEZA ($31:6180, $80)
;         and !SRAM_WORK_SCENE ($32:6000) while a Frieza scene owns it
;   VRAM  OBJ tiles $0C0-$0FF (word $6C00-$6FFF) on Frieza's scene maps
;   CGRAM one free OBJ palette (written in vblank after the game's upload)
;   DMA   channel 7 inside the field NMI (after the game's uploads)

; ---------------------------------------------------------------------------
; WRAM (!RAM_FRIEZA = $7E:DB00, $C0 bytes): bank-$7E absolute addresses.
!FZ = $DB00
assert !RAM_FRIEZA == $7E0000|!FZ, "!FZ must match !RAM_FRIEZA"
!fz_init       = !FZ+$00   ; byte: $A5 once the persistent block was checked this session
!fz_tflags     = !FZ+$01   ; byte: transient flags (!FZT_*)
!fz_lastmap    = !FZ+$02   ; word: s.lastMap ($FFFF none)
!fz_lasttick   = !FZ+$04   ; word: !core_tick of the last field frame (continuity)
!fz_pend       = !FZ+$06   ; word: deferred hook work (!FZP_*)
; current scene (frieza.js s.scene)
!fz_scene      = !FZ+$08   ; byte: kind (!FZS_*), 0 = none
!fz_sflags     = !FZ+$09   ; byte: !FZSF_COURT, !FZSF_ALTAR, !FZSF_TARGET
!fz_sage       = !FZ+$0A   ; word: age
!fz_sclock     = !FZ+$0C   ; word: clock carried from the previous scene on this map
!fz_smap       = !FZ+$0E   ; word: map of the cue
!fz_sx         = !FZ+$10   ; word: Goku's map x at the cue
!fz_sy         = !FZ+$12   ; word: Goku's map y at the cue
!fz_stx        = !FZ+$14   ; word: target x (Emperor, Fanha, Thanatos, Popoi)
!fz_sty        = !FZ+$16   ; word: target y
!fz_sbase      = !FZ+$18   ; word: target actor offset ($E000-relative)
!fz_acx        = !FZ+$1A   ; word: altar: camera x at the reveal
!fz_acy        = !FZ+$1C   ; word: altar: camera y at the reveal
!fz_lfx        = !FZ+$1E   ; word: lift: Popoi's start x
!fz_lfy        = !FZ+$20   ; word: lift: Popoi's start y
; sprite renderer (sprite.asm)
!fz_spr_buf    = !FZ+$22   ; byte: displayed VRAM buffer 0/1
!fz_spr_pal    = !FZ+$23   ; byte: OBJ palette used this frame ($FF = none drawn)
!fz_spr_res0   = !FZ+$24   ; word: frame id resident in buffer 0 ($FFFF none)
!fz_spr_res1   = !FZ+$26   ; word: frame id resident in buffer 1
!fz_spr_pend   = !FZ+$28   ; word: frame id to upload into the back buffer ($FFFF none)
!fz_spr_var    = !FZ+$2A   ; byte: palette variant this frame (0 normal, 1 red, 2 white, 3 ghost)
!fz_spr_cnt    = !FZ+$2B   ; byte: sprites added this frame
!fz_spr_x      = !FZ+$2C   ; word: draw argument: screen x of the anchor
!fz_spr_y      = !FZ+$2E   ; word: screen y of the anchor (feet)
!fz_spr_id     = !FZ+$30   ; word: frame id (atlas<<4 | tiny<<3 | frame)
!fz_spr_fl     = !FZ+$32   ; word: !FZD_* flags
!fz_spr_used   = !FZ+$34   ; byte: native OBJ palettes in use this frame (bit = palette)
!fz_music      = !FZ+$35   ; byte: Frieza cue playing (!FZM_*), 0 = native
!fz_cam_x      = !FZ+$36   ; word: camera (BG1 scroll) this frame
!fz_cam_y      = !FZ+$38   ; word
; scratch (call-local)
!fz_t0         = !FZ+$3A
!fz_t1         = !FZ+$3C
!fz_t2         = !FZ+$3E
!fz_t3         = !FZ+$40
!fz_t4         = !FZ+$42
!fz_t5         = !FZ+$44
!fz_t6         = !FZ+$46
!fz_t7         = !FZ+$48
; pose result (scene.asm fz_scene_pose)
!fz_px         = !FZ+$4A   ; word: screen x
!fz_py         = !FZ+$4C   ; word: screen y
!fz_pframe     = !FZ+$4E   ; byte: frame 0-7
!fz_mapflag    = !FZ+$4F   ; byte: 1 while the map is one of Frieza's (set on a map change)
!fz_wasidle    = !FZ+$50   ; byte: the last field frame took the idle path
!fz_room_since = !FZ+$52   ; word: core frame when the map was entered (Rider III)
!fz_atlas      = !FZ+$54   ; word: $10 when Frieza draws in his full-power form, else 0
!fz_quake      = !FZ+$56   ; byte: local quake frames left (without the fx module)
!fz_quake_prev = !FZ+$57   ; byte: $49 before the quake
!FZ_SCENE_END  = !FZ+$58
; $58-$BF: battle / challenge / death state (battle.asm, beast.asm, death.asm)

; ---- fight (battle.asm) ----
!fzf_x         = !FZ+$58   ; word: map x
!fzf_y         = !FZ+$5A   ; word: map y (the feet are y + 12)
!fzf_hp_lo     = !FZ+$5C   ; word: HP (24-bit)
!fzf_hp_hi     = !FZ+$5E   ; word
!fzf_age       = !FZ+$60   ; word
!fzf_clock     = !FZ+$62   ; word (signed): frames to the next attack
!fzf_cycle     = !FZ+$64   ; byte: attack pattern index
!fzf_node      = !FZ+$65   ; byte: current node
!fzf_nodes     = !FZ+$66   ; byte: node count (<= 6)
!fzf_tier      = !FZ+$67   ; byte: 0, 1 after the first surge
!fzf_stun      = !FZ+$68   ; byte
!fzf_grace     = !FZ+$69   ; byte
!fzf_hurt      = !FZ+$6A   ; byte
!fzf_recoil    = !FZ+$6B   ; byte
!fzf_guard     = !FZ+$6C   ; byte
!fzf_dash      = !FZ+$6D   ; byte (dash and windup are read as one word)
!fzf_windup    = !FZ+$6E   ; byte
!fzf_flags     = !FZ+$6F   ; byte: !FZFF_*
!fzf_terrain   = !FZ+$70   ; word: Goku's terrain byte at the start ($E00B)
!fzf_node_x    = !FZ+$72   ; 6 words
!fzf_node_y    = !FZ+$7E   ; 6 words
!FZF_END       = !FZ+$8A
assert !FZF_END <= !FZ+$C0, "frieza WRAM overflow"
; per-call values ($AC-$BB, after the Beast block)
!fz_hx         = !FZ+$AC   ; word: hero() x
!fz_hy         = !FZ+$AE   ; word: hero() y (feet - 12)
!fz_ax         = !FZ+$B0   ; word: point argument x (map)
!fz_ay         = !FZ+$B2   ; word: point argument y
!fz_dmg        = !FZ+$B4   ; word: damage argument
!fz_hdisc      = !FZ+$B6   ; word: hurt() from his own disc
!fz_hmelee     = !FZ+$B8   ; word: frieza_virtual_hit melee flag
!fz_sx_i       = !FZ+$BA   ; word: table index of the loop in progress
!fz_spr_pal2   = !FZ+$BC   ; byte: afterimage OBJ palette this frame ($FF none)
!fzd_on        = !FZ+$BD   ; byte: finale death running (1 here, 2 the ending's)
!fzd_key       = !FZ+$BE   ; byte: encounter of the death (!FZE_*)
!fzd_gold      = !FZ+$BF   ; byte: Goku died as a Super Saiyan
assert !FZ+$C0 <= !FZ+$C0, "frieza WRAM overflow"
; math scratch: core's call-local scratch (never used in vblank)
!fz_m0 #= (!core_scratch)&$FFFF
!fz_m1 #= !fz_m0+2
!fz_m2 #= !fz_m0+4
!fz_m3 #= !fz_m0+6
!fz_m4 #= !fz_m0+8
!fz_m5 #= !fz_m0+10
!fz_m6 #= !fz_m0+12
!fz_m7 #= !fz_m0+14

!FZFF_ACTIVE   = $01       ; s.boss exists
!FZFF_MUSCULAR = $02
!FZFF_COUNTER  = $04
!FZFF_SPACE    = $08       ; the orbit stream owns the fight (b.space)
!FZFF_LANDED   = $10       ; back on the deck after the orbital victory

!FRIEZA_HP_LO  = 96000&$FFFF
!FRIEZA_HP_HI  = 96000>>16

; Scene SRAM block (long addressing)
!FZSB          = !SRAM_WORK_SCENE+$1800
!fzs_tag       = !FZSB+$000   ; word: $5A46 ("FZ") while the block holds a fight
!fzs_wkind     = !FZSB+$002   ; byte: warning kind (!FZK_ORB/DISC/LASER), 0 none
!fzs_wage      = !FZSB+$003   ; byte
!fzs_wwait     = !FZSB+$004   ; byte
!fzs_wx        = !FZSB+$006   ; word: Frieza's position at the warning
!fzs_wy        = !FZSB+$008   ; word
!fzs_wtx       = !FZSB+$00A   ; word: the target (Goku) at the warning
!fzs_wty       = !FZSB+$00C   ; word
!fzs_rip       = !FZSB+$00E   ; byte: riposte age ($FF none)
!fzs_surge     = !FZSB+$00F   ; byte: 0 none, 1 breach (first), 2 cosmic (orbit's)
!fzs_sage      = !FZSB+$010   ; word: surge age
!fzs_lmelee    = !FZSB+$012   ; word: age of the last melee hit
!fzs_mhits     = !FZSB+$014   ; byte: meleeHits
!fzs_limpact   = !FZSB+$016   ; word: age of the last impact burst
!fzs_dischits  = !FZSB+$018   ; word
!fzs_phits     = !FZSB+$01A   ; word: playerHits
!fzs_tgx       = !FZSB+$01C   ; word: surge target (the Fortress's screen position)
!fzs_tgy       = !FZSB+$01E   ; word
; shots: 12 x 16 bytes
!FZ_SHOTS      = !FZSB+$020
!FZ_SHOT_N     = 12
!sh_kind       = $00       ; byte: 0 none, 1 orb, 2 disc, 3 laser
!sh_flip       = $01       ; byte
!sh_x          = $02
!sh_y          = $04
!sh_px         = $06       ; previous position
!sh_py         = $08
!sh_ang        = $0A       ; word: angle (orb, disc); laser: heading 0-15
!sh_speed      = $0C       ; byte: step table (0 = 3 px, 1 = 4 px)
!sh_age        = $0E       ; word
; eruptions (hazards): 4 x 8 bytes
!FZ_HAZ        = !FZSB+$0E0
!FZ_HAZ_N      = 4
!hz_on         = $00       ; byte
!hz_r          = $01       ; byte: radius
!hz_x          = $02
!hz_y          = $04
!hz_age        = $06       ; byte
!hz_wait       = $07       ; byte
; afterimages: 8 x 6 bytes
!FZ_AFTER      = !FZSB+$100
!FZ_AFTER_N    = 8
!af_age        = $00       ; byte ($FF none)
!af_x          = $02
!af_y          = $04
!fzs_test      = !FZSB+$130   ; FRIEZA_TEST mailbox: cmd, arg, result, count (words)
; arena: arena.asm (+$140-$7FF)

!FZK_ORB       = 1
!FZK_DISC      = 2
!FZK_LASER     = 3


; ---- Beast challenge and Dark Lich (beast.asm) ----
!fzl_base       = !FZ+$8A   ; word: Dark Lich actor offset ($FFFF none)
!fzl_map        = !FZ+$8C   ; word: his map
!fzl_clock      = !FZ+$8E   ; word
!fzl_last       = !FZ+$90   ; word: clock of the last boost
!fzl_buffs      = !FZ+$92   ; byte: boosts given (<= 2)
!fzl_boost      = !FZ+$93   ; byte: boost visual age ($FF none)
!fzx_body       = !FZ+$94   ; word: Beast actor offset whose HP was raised ($FFFF none)
!fzx_clock      = !FZ+$96   ; word: frames to the next eruption
!fzx_grace      = !FZ+$98   ; byte
!fzx_hits       = !FZ+$99   ; byte
!fzx_bon        = !FZ+$9A   ; byte: an eruption is on
!fzx_bhit       = !FZ+$9B   ; byte: it struck Goku
!fzx_bx         = !FZ+$9C   ; word: lane x (map)
!fzx_btop       = !FZ+$9E   ; word: lane top (map y)
!fzx_bbot       = !FZ+$A0   ; word: lane bottom
!fzx_bwidth     = !FZ+$A2   ; word
!fzx_bwarn      = !FZ+$A4   ; word: warning frames
!fzx_bdmg       = !FZ+$A6   ; word
!fzx_bage       = !FZ+$A8   ; word
!fzx_pending    = !FZ+$AA   ; word: the eruption's damage queued on Goku (pendingBeam)
!FZX_END        = !FZ+$AC
assert !FZX_END <= !FZ+$C0, "frieza WRAM overflow (beast)"

!FZ_SPECIES_BEAST = 127
!FZ_SPECIES_LICH  = 121


; ---- broken deck (arena.asm) ----
!FZ_HOLES      = !FZSB+$400   ; 1 KiB bitmap: row stride 16 bytes
!fzs_arena_map = !FZSB+$140   ; word: map the bitmap belongs to ($FFFF none)
!fzs_arena_rev = !FZSB+$142   ; word: revision (fractures so far)
!fzs_holes_n   = !FZSB+$144   ; word: cells broken
!fzd_age       = !FZSB+$146   ; word: finale death clock (long addressing)
; holes on the screen (holes.asm): $32:7000-77FF (the orbit stream keeps to
; $32:6000-6FFF while the fight is in space)
!FZHB          = !SRAM_WORK_SCENE+$1000
!fzh_count     = !FZHB+$000   ; word: listed hole cells
!fzh_key       = !FZHB+$002   ; word: camera tile key of the last rebuild ($FFFF: rebuild)
!fzh_wcount    = !FZHB+$004   ; word: tilemap rows in the write list
!fzh_wcursor   = !FZHB+$006   ; word: rows written so far
!fzh_tiles     = !FZHB+$008   ; byte: hole tiles 0 needed, 1 wanted, 2 in VRAM (set in vblank)
!FZ_HLIST      = !FZHB+$010   ; 400 x 3 bytes: cx, cy, broken neighbours (W1 E2 N4 S8)
!FZ_HWRITE     = !FZHB+$500   ; 64 x 6 bytes: VRAM address, two tilemap entries
!fzs_palmask   = !FZHB+$680   ; 8 bytes: native OBJ palettes seen per 16-slot chunk
!fzs_palframe  = !FZHB+$688   ; word: core frame of the last palette scan
; !FZHB+$700: the large-burst table (effects.asm)
!fzv_on        = !FZSB+$14A   ; byte: the victory beat runs
!fzv_age       = !FZSB+$14C   ; word: frames since the fatal hit
!fzv_x         = !FZSB+$14E   ; word: where Frieza fell (map)
!fzv_y         = !FZSB+$150   ; word
!fzv_white     = !FZSB+$152   ; byte: whiteout 0-31 this frame


; boss-victory.js bossVictoryTiming (frames from the fatal hit)
!FZV_FADE      = 143
!FZV_WHITE     = 306
!FZV_VANISH    = 326
!FZV_JINGLE    = 375
!FZV_REVEAL    = 631
!FZV_CLEAR     = 791
!FZV_ACQUIRE   = 375+540          ; the chime once the 540-frame fanfare ends
!FZV_DONE      = 375+540+120      ; then the 120-frame hold before travel

; transient flags (!fz_tflags)
!FZT_VRAM_OK   = $01       ; this map's Frieza VRAM region holds our buffers
!FZT_FORCED    = $02       ; the frame ran under forced blank (map load)
!FZT_PALSCAN   = $04       ; native OBJ palettes scanned this frame
!FZT_LOCKED    = $08       ; the input lock is applied
; per-frame permissions for the vblank handler (set by this frame's field
; logic only, so stale scene SRAM never reaches VRAM or the PPU)
!FZT_HOLES     = $10       ; the broken floor is drawn this frame
!FZT_WHITE     = $20       ; the victory whiteout is on this frame
!FZT_WPREV     = $40       ; it was on last frame (the vblank restores)
!FZT_DANGER    = $80       ; combat was told the encounter is dangerous

; deferred work (!fz_pend), applied in the next field frame callback
!FZW_FADE      = $0001     ; trial fade (C0:8B16's ordinary 60-frame fade)
!FZW_POPOI     = $0002     ; showdown: descriptor for an unrecruited Popoi
!FZW_CANCEL    = $0004     ; cancelCombat + land local flight
!FZW_FORM_BASE = $0008     ; showdown: back to base form
!FZW_FORM_SSJ  = $0010     ; gold: permanent Super Saiyan
!FZW_REVIVE    = $0020     ; revive: companions back to full health
!FZW_EMP_HIDE  = $0040     ; emperor-fall: hide his actor at age 12

; ---------------------------------------------------------------------------
; Persistent block (!PERSIST_FRIEZA, $80 bytes of battery SRAM, long
; addressing). Saved with every GAME FILE by core's sidecar.
!FZPB = !PERSIST_FRIEZA
!fzp_version    = !FZPB+$00   ; byte: 1 once initialised (0: derive from native flags)
!fzp_stage      = !FZPB+$01   ; byte: !FZST_*
!fzp_tree       = !FZPB+$02   ; byte: !FZTR_*
!fzp_flags      = !FZPB+$03   ; word: !FZFL_*
!fzp_mask       = !FZPB+$05   ; byte: stolenMask (Balls Frieza took)
!fzp_crisis     = !FZPB+$06   ; byte: !FZC_*
!fzp_beast      = !FZPB+$07   ; byte: !FZX_* (Beast challenge)
!fzp_flyby      = !FZPB+$08   ; word: flyby age ($FFFF = none)
; $0A-$3F free (Frieza); $40-$7F reserved for the orbit stream (frieza.md)
!FZPB_ORBIT      = !FZPB+$40

!FZFL_EMPEROR    = $0001     ; emperorKilled
!FZFL_TRIAL_WON  = $0002
!FZFL_STOLEN     = $0004     ; Frieza holds the Balls (unresolved)
!FZFL_EIGHTH     = $0008     ; Dryad's eighth Ball
!FZFL_PERMANENT  = $0010     ; permanent Super Saiyan
!FZFL_FALLEN     = $0020     ; Popoi fell
!FZFL_POPOI      = $0040     ; popoiMember
!FZFL_PRIMM      = $0080     ; primmMember
!FZFL_DECKBALL   = $0100
!FZFL_OUTDOOR    = $0200     ; outdoorIntro
!FZFL_HINTED     = $0400
!FZFL_OFFERED    = $0800
!FZFL_FLYBY      = $1000     ; flyby armed
!FZFL_FLYBY_GO   = $2000     ; flyby started (1F04 running)

!FZC_ON         = $01       ; a crisis object exists
!FZC_ACTIVE     = $02
!FZC_RESOLVED   = $04
!FZC_NOTIFIED   = $08       ; flightNotified
!FZC_DEATHBALL  = $10
!FZC_REAR       = $20       ; rearCamera requested

!FZX_FED        = $01
!FZX_STARTED    = $02
!FZX_WON        = $04

; stages (frieza.js s.stage)
!FZST_DORMANT  = 0
!FZST_THEFT    = 1
!FZST_PALACE   = 2
!FZST_HUNT     = 3
!FZST_TRIAL    = 4
!FZST_SHOWDOWN = 5
!FZST_BATTLE   = 6
!FZST_WON      = 7
!FZST_DEFEATED = 8
; tree (s.tree)
!FZTR_NONE     = 0
!FZTR_PURSUIT  = 1
!FZTR_CONFRONT = 2
!FZTR_ATTACK   = 3
!FZTR_COMPLETE = 4

; scene kinds (s.scene.kind)
!FZS_WAITING        = 1
!FZS_EMPEROR_WAIT   = 2
!FZS_TRIAL_ENTRY    = 3
!FZS_TRIAL_TAUNT    = 4
!FZS_EMPOWER        = 5
!FZS_TRIAL_LEAVE    = 6
!FZS_ALTAR_LEAVE    = 7
!FZS_TEMPLE_EXIT    = 8
!FZS_CORE_ARRIVAL   = 9
!FZS_FANHA          = 10
